using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AutoTurretEffect", menuName = "Data/Battle/Effects/AutoTurret Effect")]
public class AutoTurretEffect : Effect
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("VFX Animation")]
	[SerializeField]
	private float vfxDelay;

	[SerializeField]
	private AnimationCurve fireTrailAnimationCurve;

	[Header("Description")]
	[SerializeField]
	private BattleAction battleAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedAtTheStartOfItsTurn = base.localizationManager.GetLocalizedAtTheStartOfItsTurn(withSpace: true);
		string actionDescription = battleAction.GetActionDescription(amount);
		return string.Concat(localizedAtTheStartOfItsTurn + actionDescription.LowercaseFirst(), AppendedDescription());
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.InsertAsNextStartOfTurnAction(AutoTurretCoroutine(effectAmount, effectOwner, null));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(AutoTurretCoroutine(effectAmount, effectOwner, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator AutoTurretCoroutine(int effectAmount, GameObject effectOwner, GameObject target)
	{
		List<GameObject> activeCorruptedAnimals = currentCorruptedAnimals.activeCorruptedAnimals;
		if (activeCorruptedAnimals.Count <= 0 || effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			yield break;
		}
		SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 3f);
		PlayEffectActivationSFX();
		CompanionEffects component = effectOwner.GetComponent<CompanionEffects>();
		GameObject gameObject;
		if (target != null)
		{
			gameObject = target;
			component.IsEffectActive(component.CompanionEffectsList.LockOnEffect);
		}
		else
		{
			gameObject = activeCorruptedAnimals.PickRandom();
		}
		CorruptionStats corruptionsStats = gameObject.GetComponent<CorruptionStats>();
		component.IsEffectActive(this);
		yield return new WaitForSeconds(0.4f);
		if (IsVFXEnabled())
		{
			GameObject trailVFX = GetVFX(GetVFXOwnerPosition(effectOwner));
			Vector3 startPosition = trailVFX.transform.position;
			Vector3 targetPosition = GetVFXOwnerPosition(corruptionsStats.gameObject);
			SpawnThirdVFX(GetVFXOwnerPosition(effectOwner), 3f);
			yield return ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(CoroutineUtility.CurveRoutine(vfxDelay, fireTrailAnimationCurve, delegate(float t, float v)
			{
				trailVFX.transform.position = Vector3.Lerp(startPosition, targetPosition, v);
			}));
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(trailVFX, 3f);
			SpawnThirdVFX(GetVFXOwnerPosition(corruptionsStats.gameObject), 3f);
		}
		corruptionsStats.Purify(effectAmount, null);
		yield return new WaitForSeconds(0.6f);
	}
}
